def shortest_path(graph, source, target):
    if source == target:
        return (float('inf'), None)

    def bfs(graph, source, target):
        queue = [source]
        visited = {source}
        parent = dict()
        while queue:
            node = queue.pop(0)
            for neighbor, weight in graph[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    parent[neighbor] = (node, weight)
                    if neighbor == target:
                        return (True, parent)
                    queue.append(neighbor)
        return (False, parent)

    def shortest_path_dijkstra(graph, source, target):
        distances = defaultdict(lambda: float('inf'))
        distances[source] = 0
        parent = {}
        while True:
            node = min(distances, key=distances.get)
            if distances[node] == float('inf'):
                return (float('inf'), None)
            if node == target:
                path = []
                while node:
                    path.append(node)
                    node, weight = parent[node]
                return (distances[target], list(reversed(path)))
            for neighbor, weight in graph[node]:
                if distances[node] + weight < distances[neighbor]:
                    distances[neighbor] = distances[node] + weight
                    parent[neighbor] = (node, weight)
    result = shortest_path_dijkstra(graph, source, target)
    if result[0] < float('inf'):
        return result
    found, parent = bfs(graph, source, target)
    if not found:
        return (float('inf'), None)
    path = []
    node = target
    while node != source:
        node, weight = parent[node]
        path.append(node)
    path.reverse()
    return (distances[target], path)
